-- Two drawn pictures for every new product: the sock on its own, and the pair (or the open box).
insert into product_image (product_id, url, alt, position)
select p.id, '/media/products/' || p.slug || '-1.svg', p.name || ' - AK&VEN', 0
  from product p
 where not exists (select 1 from product_image i where i.product_id = p.id and i.position = 0);

insert into product_image (product_id, url, alt, position)
select p.id, '/media/products/' || p.slug || '-2.svg', p.name || ', the pair - AK&VEN', 1
  from product p
 where not exists (select 1 from product_image i where i.product_id = p.id and i.position = 1);

-- A picture of each colour, shown when the colour is chosen.
