    ('oimo-mid-men', 'Black', '/media/products/oimo-mid-men--black-1.svg', '/media/products/oimo-mid-men--black-2.svg', 4),
    ('tunduk-crew', 'Brick', '/media/products/tunduk-crew--brick-1.svg', '/media/products/tunduk-crew--brick-2.svg', 2),
    ('tunduk-crew', 'Forest', '/media/products/tunduk-crew--forest-1.svg', '/media/products/tunduk-crew--forest-2.svg', 4),
    ('ala-too-kids', 'Sky', '/media/products/ala-too-kids--sky-1.svg', '/media/products/ala-too-kids--sky-2.svg', 2),
    ('ala-too-kids', 'Mint', '/media/products/ala-too-kids--mint-1.svg', '/media/products/ala-too-kids--mint-2.svg', 4)
) as v(slug, color, url1, url2, pos)
cross join lateral (values (v.url1, v.pos, v.color, ''), (v.url2, v.pos + 1, v.color, ', the pair')) as x(url, pos, color, what)
join product p on p.slug = v.slug
where not exists (select 1 from product_image i where i.product_id = p.id and i.position = x.pos);
